  function mF(n){if(!n)return'$0';if(n>=1e6)return'$'+(n/1e6).toFixed(2).replace(/\\.?0+$/,'')+'M';if(n>=1e3)return'$'+Math.round(n/1e3)+'K';return'$'+n;}
