    sv('k-total',tot);sv('k-ongoing',ongoing);sv('k-demos',demos);sv('k-wins',wins);sv('k-losses',lost);sv('k-customers',custs);
    var cACV=all.filter(function(r){return r.s==='Win';}).reduce(function(a,r){return a+(r.a||0);},0);
