  function chartACV(rows){var map={};rows.forEach(function(r){var v=r.a||0;if(!v)return;if(!map[r.p])map[r.p]={closed:0,open:0};if(r.s==='Win')map[r.p].closed+=v;else if(r.s!=='Lost')map[r.p].open+=v;});var entries=Object.entries(map).map(function(e){return[e[0],Object.assign({},e[1],{total:e[1].closed+e[1].open})];}).sort(function(a,b){return b[1].total-a[1].total;});if(entries.length>12)entries=entries.slice(0,12);var W=1000,H=Math.max(380,50+entries.length*38),pL=170,pR=150,pT=22,plotW=W-pL-pR,rowH=22,rowGap=14,maxV=Math.max(1,Math.max.apply(null,entries.length?entries.map(function(e){return e[1].total;}):[0])),svg='<g class="wAf"><rect x="'+pL+'" y="0" width="14" height="14" rx="2" fill="'+gC('--wwin')+'"/><text x="'+(pL+22)+'" y="12" fill="'+gC('--wmute')+'" font-family="DM Sans" font-size="12">Closed (won)</text><rect x="'+(pL+140)+'" y="0" width="14" height="14" rx="2" fill="'+gC('--wacc2')+'" opacity=".85"/><text x="'+(pL+162)+'" y="12" fill="'+gC('--wmute')+'" font-family="DM Sans" font-size="12">Open pipeline</text></g>',totC=0,totO=0;entries.forEach(function(e,i){var p=e[0],c=e[1],y=pT+i*(rowH+rowGap),cy=y+rowH/2+5;totC+=c.closed;totO+=c.open;svg+='<text class="wpl" x="'+(pL-12)+'" y="'+cy+'" text-anchor="end">'+p+'</text>';var x=pL;if(c.closed>0){var w=(c.closed/maxV)*plotW,tip='<div class="th">'+p+'</div><div class="tr"><span>Closed</span><b>'+mF(c.closed)+'</b></div><div class="tr"><span>Open</span><b>'+mF(c.open)+'</b></div>';svg+='<rect class="wseg wAh" x="'+x+'" y="'+y+'" width="'+w+'" height="'+rowH+'" rx="3" fill="'+gC('--wwin')+'" dt="'+encodeURIComponent(tip)+'" style="animation-delay:'+(i*50)+'ms"></rect>';x+=w;}if(c.open>0){var w2=(c.open/maxV)*plotW,tip2='<div class="th">'+p+'</div><div class="tr"><span>Closed</span><b>'+mF(c.closed)+'</b></div><div class="tr"><span>Open</span><b>'+mF(c.open)+'</b></div>';svg+='<rect class="wseg wAh" x="'+x+'" y="'+y+'" width="'+w2+'" height="'+rowH+'" rx="3" fill="'+gC('--wacc2')+'" opacity=".85" dt="'+encodeURIComponent(tip2)+'" style="animation-delay:'+(i*50)+'ms"></rect>';x+=w2;}svg+='<text class="wbn wAf" x="'+(x+10)+'" y="'+cy+'" style="animation-delay:'+(i*50+350)+'ms">'+mF(c.total)+'</text>';});setSVG(svg,W,H,'Closed '+mF(totC)+' \xb7 Open '+mF(totO)+' \xb7 '+entries.length+' partners');}
  function render(){var rows=FR();renderKPIs();renderLegend();hideTip();if(!rows.length){setSVG('<text x="500" y="230" text-anchor="middle" fill="'+gC('--wmute')+'" font-family="DM Sans" font-size="14">No pipeline data for this filter</text>',1000,460,'0 rows');return;}if(ST.tab==='timeline')chartTimeline(rows);else if(ST.tab==='companies')chartCompanies(rows);else if(ST.tab==='motion')chartMotion(rows);else if(ST.tab==='stages')chartStages(rows);else if(ST.tab==='substages')chartSubstages(rows);else if(ST.tab==='acv')chartACV(rows);}
  document.querySelectorAll('.wtab').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('.wtab').forEach(function(x){x.classList.remove('active');});b.classList.add('active');ST.tab=b.dataset.wt;render();});});
  renderFilters();
